/// Parse a Value::Array of `{ provider, model }` objects into candidates.
fn parse_candidates(val: Value) -> Vec<TierRouteCandidate> {
    let mut out: Vec<TierRouteCandidate> = vec![];
    match val {
        Value::Array(arr) => {
            for v in &arr.values {
                match v {
                    Value::Obj(o) => {
                        let provider = obj_get_str(o.clone(), "provider");
                        let model = obj_get_str(o.clone(), "model");
                        if provider.is_empty() == false && model.is_empty() == false {
                            out.push(TierRouteCandidate { provider: provider.to_string(), model: model.to_string() });
                        }
                    },
                    _ => {},
                };
            }
        },
        _ => {},
    };
    return out;
}

/// Read a string prop; "" when missing or nil.
fn opt_str(node: Node, key: &str) -> String {
    let val = node.get_prop_of(key);
    match val {
        Value::Str(s) => return s.to_string(),
        Value::String(s) => return s.to_string(),
        _ => return val.to_astr().to_string(),
    }
}

/// Read an optional string prop: None when missing/nil.
fn opt_str_opt(node: Node, key: &str) -> Option<String> {
    let val = node.get_prop_of(key);
    match val {
        Value::Str(s) => return Some(s.to_string()),
        Value::String(s) => return Some(s.to_string()),
        _ => {
            let s = val.to_astr().to_string();
            if s.is_empty() {
                return None;
            }
            return Some(s);
        },
    }
}

/// Read a non-negative integer prop; None when missing.
fn opt_uint_opt(node: Node, key: &str) -> Option<u32> {
    let val = node.get_prop_of(key);
    match val {
        Value::Uint(u) => return Some(u as u32),
        Value::Int(i) => {
            if i >= 0 {
                return Some(i as u32);
            }
            return None;
        },
        _ => return None,
    }
}

/// Read an optional uint prop (kept for parity with opt_uint in the original).
fn opt_uint(node: Node, key: &str) -> Option<u32> {
    return opt_uint_opt(node.clone(), key);
}

/// Read a boolean prop: true/false/1/0/yes/no. None if absent/unrecognized.
fn opt_bool(node: Node, key: &str) -> Option<bool> {
    let val = node.get_prop_of(key);
    match val {
        Value::Bool(b) => return Some(b),
        Value::Uint(u) => return Some(u != 0),
        Value::Int(i) => return Some(i != 0),
        Value::Str(s) => {
            let lower = s.to_ascii_lowercase();
            match lower.as_str() {
                "true" => return Some(true),
                "yes" => return Some(true),
                "1" => return Some(true),
                "on" => return Some(true),
                "false" => return Some(false),
                "no" => return Some(false),
                "0" => return Some(false),
                "off" => return Some(false),
                _ => return None,
            };
        },
        _ => return None,
    }
}

/// Read the `models` field as a list of [ModelDefinition]s (id + tier).
/// 
/// Accepted shapes (each element of the `models` array):
/// - `Obj { id, name?, tier }` — full, preferred.
/// - `Str "glm-5.2"` — bare model id, defaults to [ModelTier.Mid].
/// Legacy: a comma-separated bare string `glm-4.6,glm-flash` → all Mid.
fn opt_models(node: Node, key: &str) -> Vec<ModelDefinition> {
    let val = node.get_prop_of(key);
    let mut out: Vec<ModelDefinition> = vec![];
    match val {
        Value::Array(arr) => {
            for el in &arr.values {
                match el {
                    Value::Obj(o) => {
                        let id = obj_get_str(o.clone(), "id");
                        if id.is_empty() == false {
                            let name = obj_get_str(o.clone(), "name");
                            let tier = parse_tier(obj_get_str(o.clone(), "tier").as_str());
                            out.push(ModelDefinition { id: id, name: name, tier: tier });
                        }
                    },
                    Value::Str(s) => {
                        

                        out.push(ModelDefinition::new(s.as_str(), ModelTier::Mid));
                    },
                    _ => {},
                };
            }
        },
        Value::Str(s) => {
            

            let parts = s.split(",").collect::<Vec<_>>();
            for raw in &parts {
                let m = raw.trim().to_string();
                if m.is_empty() == false {
                    out.push(ModelDefinition::new(m.as_str(), ModelTier::Mid));
                }
            }
        },
        _ => {},
    };
    return out;
}

/// Parse a tier name → ModelTier. Accepts snake_case ("max", "mid"), display
/// ("Max", "Mid"), and auto-forge aliases ("large"=Pro, "heavy"=Max).
/// 
/// Unknown → Min. NOTE: loader.rs:315 comments "unknown names default to Mid"
/// but the code is `parse_name(s).unwrap_or_default()`, and ModelTier's
/// `#[default]` is Min (tier.rs:18) — so the actual Rust behavior is Min.
/// This port matches the **code** (Min), not the (self-contradictory) comment.
fn parse_tier(s: &str) -> ModelTier {
    match ModelTier::parse_name(s) {
        Some(t) => return t,
        None => return ModelTier::Min,
    }
}

/// Read a string field from an Obj, or "" if absent / not a string.
fn obj_get_str(o: Obj, key: &str) -> String {
    match o.get(key) {
        Some(v) => {
            match v {
                Value::Str(s) => return s.to_string(),
                Value::String(s) => return s.to_string(),
                _ => return "".to_string(),
            };
        },
        None => return "".to_string(),
    }
}

/// Extract the str payload from a ValueKey::Str, else "".
fn valuekey_to_str(k: ValueKey) -> String {
    match k {
        ValueKey::Str(s) => return s.to_string(),
        _ => return "".to_string(),
    }
}
